class Solution {
  public int countTrapezoids(int[][] points) {
    final long MOD = 1_000_000_007L;
    Map<Integer, Long> perRow = new HashMap<>();
    for (int[] p : points) perRow.merge(p[1], 1L, Long::sum);
    long sum = 0, squares = 0;
    for (long c : perRow.values()) {
      long pairs = (c * (c - 1) / 2) % MOD; // horizontal segments available in this row
      sum = (sum + pairs) % MOD;
      squares = (squares + pairs * pairs) % MOD;
    }
    long inverseTwo = (MOD + 1) / 2;
    // choose two segments from two different rows
    return (int) ((sum * sum % MOD - squares + MOD) % MOD * inverseTwo % MOD);
  }
}
